import{at as e,it as t,t as n,vt as r}from"./chunks/framework.DkAysg6d.js";var i=JSON.parse(`{"title":"Range selection and focus","description":"","frontmatter":{},"headers":[],"relativePath":"cells-range.md","filePath":"pages/cells-range.md"}`),a={name:`cells-range.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="range-selection-and-focus" tabindex="-1">Range selection and focus <a class="header-anchor" href="#range-selection-and-focus" aria-label="Permalink to “Range selection and focus”">​</a></h1><p>Drag a block of cells, extend it, and read back the keys inside it. Focus is the single cell the keyboard is standing on.</p><p>No panel runs on this page, because no example in <code>examples/index.ts</code> covers ranges. Range dragging is live on the <a href="/hafley-rxjs/signal-grid/showcase-everything">Everything table</a> route.</p><h2 id="two-different-keys" tabindex="-1">Two different keys <a class="header-anchor" href="#two-different-keys" aria-label="Permalink to “Two different keys”">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>holds</th><th>covered by</th></tr></thead><tbody><tr><td><code>state.rowSelection</code></td><td>whole rows, keyed by row id</td><td><a href="/hafley-rxjs/signal-grid/rows-select">Select</a></td></tr><tr><td><code>state.selection</code></td><td>a range of cells, as blocks</td><td>this page</td></tr><tr><td><code>state.focus</code></td><td>one <code>CellId</code>, or nothing</td><td>this page</td></tr></tbody></table><h2 id="the-range-model" tabindex="-1">The range model <a class="header-anchor" href="#the-range-model" aria-label="Permalink to “The range model”">​</a></h2><p><code>src/15_selection.ts</code> holds the arithmetic as pure functions over a <code>GridSelection</code>.</p><table tabindex="0"><thead><tr><th>function</th><th>what it answers</th></tr></thead><tbody><tr><td><code>beginAt</code></td><td>start a new block at an anchor</td></tr><tr><td><code>extendTo</code></td><td>move the live block&#39;s head</td></tr><tr><td><code>commitBlock</code></td><td>fold the live block into the committed list</td></tr><tr><td><code>blocksOf</code></td><td>every block, committed plus live</td></tr><tr><td><code>rectOf</code></td><td>the keys a block covers, as a vertical and a horizontal list</td></tr><tr><td><code>isSelected</code></td><td>whether one cell is in the range</td></tr><tr><td><code>selectedKeys</code></td><td>every cell id in the range</td></tr></tbody></table><p><code>SelectionMode</code> is <code>cell</code>, <code>row</code>, or <code>column</code>, which is what makes a header drag select whole columns and a gutter drag select whole rows through the same block arithmetic.</p><h2 id="the-three-drag-epics" tabindex="-1">The three drag epics <a class="header-anchor" href="#the-three-drag-epics" aria-label="Permalink to “The three drag epics”">​</a></h2><table tabindex="0"><thead><tr><th>epic in <code>src/7_epics.ts</code></th><th>started by</th></tr></thead><tbody><tr><td><code>selectCellsOnDrag</code></td><td>a press on a data cell</td></tr><tr><td><code>selectRowsOnDrag</code></td><td>a press on the gutter</td></tr><tr><td><code>selectColumnsOnDrag</code></td><td>a press on a header</td></tr></tbody></table><h2 id="a-range-over-a-group-heading" tabindex="-1">A range over a group heading <a class="header-anchor" href="#a-range-over-a-group-heading" aria-label="Permalink to “A range over a group heading”">​</a></h2><p>A heading is one box across the row and owns no cell in any column, so a range never stamps one and a drag cannot start on one. The block still spans it: the range is two addresses over the flat key list, so the leaves above and below a heading stay in one rectangle.</p><p><code>data-selected</code> on a row and <code>data-selected</code> on a cell are two different features. The row&#39;s is <code>state.rowSelection</code>, the cell&#39;s is range membership, and <code>--sg-selected-bg</code> and <code>--sg-range-bg</code> are the two blues that say so.</p><p>Every one of them gates on the primary button, so a right click inside a selected block raises a menu intent and leaves the range exactly as the reader can still see it.</p><h2 id="what-the-renderer-stamps" tabindex="-1">What the renderer stamps <a class="header-anchor" href="#what-the-renderer-stamps" aria-label="Permalink to “What the renderer stamps”">​</a></h2><table tabindex="0"><thead><tr><th>attribute</th><th>on</th><th>meaning</th></tr></thead><tbody><tr><td><code>data-selected</code></td><td>a cell</td><td>it is inside the range</td></tr><tr><td><code>data-edge</code></td><td>a cell</td><td>which sides of the block it sits on, as a space-separated list</td></tr></tbody></table><p>Reading state as attributes rather than classes means a stylesheet rule and a test assertion match the same thing.</p><h2 id="focus" tabindex="-1">Focus <a class="header-anchor" href="#focus" aria-label="Permalink to “Focus”">​</a></h2><p><code>state.focus</code> is written by <code>keyboardNav</code> in <code>src/7_epics.ts</code> and by a plain cell click. Arrow keys step it through the flat list, clamped at both ends, and Space or Enter acts on the row it names.</p><p>Nothing paints a focus ring. <code>state.focus</code> has no renderer today, so a grid that needs a visible caret draws it from a cell slot reading the key. The <code>focus</code> state key is recorded as declared and not run in the parity ledger.</p><h2 id="inline-editing" tabindex="-1">Inline editing <a class="header-anchor" href="#inline-editing" aria-label="Permalink to “Inline editing”">​</a></h2><p><code>state.editing</code> is read by <code>src/10_render.ts</code> and written by no epic, so an editor slot mounts only when your code writes the key. The form lifecycle stays with the consumer by decision.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};